PRAGMA foreign_keys=ON;
CREATE TABLE tenants(id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL, owner_id TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'trial', plan TEXT NOT NULL DEFAULT 'pro', settings TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL);
CREATE TABLE members(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), user_id TEXT, email TEXT NOT NULL, name TEXT NOT NULL, role TEXT NOT NULL, outlet_id TEXT, partner_id TEXT, active INTEGER NOT NULL DEFAULT 1, UNIQUE(tenant_id,email));
CREATE TABLE platform_admins(user_id TEXT PRIMARY KEY);
CREATE TABLE records(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),kind TEXT NOT NULL,data TEXT NOT NULL,deleted_at INTEGER,created_at INTEGER NOT NULL);
CREATE INDEX records_tenant ON records(tenant_id,kind,deleted_at);
CREATE TABLE products(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),name TEXT NOT NULL,category TEXT NOT NULL,brand TEXT,description TEXT,price INTEGER NOT NULL CHECK(price>=0),image TEXT,capacity INTEGER NOT NULL DEFAULT 1,buffer_hours INTEGER, published INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER,created_at INTEGER NOT NULL);
CREATE INDEX products_tenant ON products(tenant_id,deleted_at,category);
CREATE TABLE units(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),product_id TEXT NOT NULL REFERENCES products(id),outlet_id TEXT NOT NULL,code TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'available',condition_note TEXT,purchase_price INTEGER NOT NULL DEFAULT 0,partner_id TEXT,created_at INTEGER NOT NULL,UNIQUE(tenant_id,code));
CREATE INDEX units_tenant ON units(tenant_id,product_id,outlet_id,status);
CREATE TABLE customers(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),name TEXT NOT NULL,phone TEXT NOT NULL,email TEXT,address TEXT,id_doc TEXT,blacklisted INTEGER NOT NULL DEFAULT 0,notes TEXT,segment TEXT NOT NULL DEFAULT 'baru',created_at INTEGER NOT NULL,UNIQUE(tenant_id,phone));
CREATE INDEX customers_tenant ON customers(tenant_id,name);
CREATE TABLE bookings(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),outlet_id TEXT NOT NULL,customer_id TEXT NOT NULL REFERENCES customers(id),code TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending_payment',channel TEXT NOT NULL,start_at INTEGER NOT NULL,end_at INTEGER NOT NULL,subtotal INTEGER NOT NULL,discount INTEGER NOT NULL DEFAULT 0,total INTEGER NOT NULL CHECK(total>=0),paid INTEGER NOT NULL DEFAULT 0 CHECK(paid>=0 AND paid<=total),dp INTEGER NOT NULL DEFAULT 0,expires_at INTEGER,collateral TEXT NOT NULL DEFAULT 'none',collateral_type TEXT,note TEXT,idem TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(tenant_id,code),UNIQUE(tenant_id,idem));
CREATE INDEX bookings_tenant ON bookings(tenant_id,status,start_at);
CREATE TABLE items(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,booking_id TEXT NOT NULL REFERENCES bookings(id),product_id TEXT NOT NULL,unit_id TEXT NOT NULL REFERENCES units(id),product_name TEXT NOT NULL,price INTEGER NOT NULL,days INTEGER NOT NULL,total INTEGER NOT NULL,returned_at INTEGER,condition TEXT);
CREATE INDEX items_tenant ON items(tenant_id,booking_id);
CREATE TABLE reservations(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,unit_id TEXT NOT NULL REFERENCES units(id),booking_id TEXT,start_at INTEGER NOT NULL,end_at INTEGER NOT NULL,kind TEXT NOT NULL DEFAULT 'booking',released_at INTEGER,CHECK(end_at>start_at));
CREATE INDEX reservations_tenant ON reservations(tenant_id,unit_id,start_at,end_at) WHERE released_at IS NULL;
CREATE TRIGGER no_overlap_insert BEFORE INSERT ON reservations WHEN NEW.released_at IS NULL AND EXISTS(SELECT 1 FROM reservations r WHERE r.tenant_id=NEW.tenant_id AND r.unit_id=NEW.unit_id AND r.released_at IS NULL AND r.start_at<NEW.end_at AND NEW.start_at<r.end_at) BEGIN SELECT RAISE(ABORT,'UNIT_NOT_AVAILABLE'); END;
CREATE TRIGGER no_overlap_update BEFORE UPDATE OF start_at,end_at,released_at ON reservations WHEN NEW.released_at IS NULL AND EXISTS(SELECT 1 FROM reservations r WHERE r.id<>NEW.id AND r.tenant_id=NEW.tenant_id AND r.unit_id=NEW.unit_id AND r.released_at IS NULL AND r.start_at<NEW.end_at AND NEW.start_at<r.end_at) BEGIN SELECT RAISE(ABORT,'UNIT_NOT_AVAILABLE'); END;
CREATE TABLE payments(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,booking_id TEXT NOT NULL REFERENCES bookings(id),amount INTEGER NOT NULL CHECK(amount>0),method TEXT NOT NULL,kind TEXT NOT NULL DEFAULT 'rental',status TEXT NOT NULL DEFAULT 'pending',proof TEXT,idem TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(tenant_id,idem));
CREATE INDEX payments_tenant ON payments(tenant_id,status,booking_id);
CREATE TABLE ledger(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,booking_id TEXT,account TEXT NOT NULL,direction TEXT NOT NULL CHECK(direction IN('in','out')),amount INTEGER NOT NULL CHECK(amount>0),reference TEXT UNIQUE,note TEXT,created_at INTEGER NOT NULL);
CREATE INDEX ledger_tenant ON ledger(tenant_id,created_at);
CREATE TRIGGER ledger_no_update BEFORE UPDATE ON ledger BEGIN SELECT RAISE(ABORT,'LEDGER_IMMUTABLE'); END;
CREATE TRIGGER ledger_no_delete BEFORE DELETE ON ledger BEGIN SELECT RAISE(ABORT,'LEDGER_IMMUTABLE'); END;
CREATE TABLE status_logs(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,booking_id TEXT NOT NULL,status TEXT NOT NULL,note TEXT,created_at INTEGER NOT NULL);
CREATE INDEX logs_tenant ON status_logs(tenant_id,booking_id,created_at);
CREATE TABLE audit(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,user_id TEXT NOT NULL,action TEXT NOT NULL,entity_id TEXT,ip TEXT,created_at INTEGER NOT NULL);
CREATE INDEX audit_tenant ON audit(tenant_id,created_at);
CREATE TABLE uploads(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,kind TEXT NOT NULL,owner_token TEXT NOT NULL,mime TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE INDEX uploads_tenant ON uploads(tenant_id,kind);
CREATE TABLE rate_limits(key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE operation_keys(tenant_id TEXT NOT NULL,key TEXT NOT NULL,PRIMARY KEY(tenant_id,key));
